// h[] heap of ids, key[id] priorities, pos[id] slot
void up(int i){ while(i&&key[h[i]]<key[h[(i-1)/2]]){swap(pos[h[i]],pos[h[(i-1)/2]]);swap(h[i],h[(i-1)/2]);i=(i-1)/2;} }
void down(int i){ for(;;){int c=2*i+1;if(c>=n)break;if(c+1<n&&key[h[c+1]]<key[h[c]])c++;if(key[h[i]]<=key[h[c]])break;swap(pos[h[i]],pos[h[c]]);swap(h[i],h[c]);i=c;} }
void decreaseKey(int id,ll nk){ key[id]=nk; up(pos[id]); }   // min-heap: only up
